"""Write the Volta launch files of DeepGEMM's sm100 kernels from deepgemm.py's JSON.

    python3 external/ptx/deepgemm/launches.py

Each kernel runs as DeepJIT launches it (deepgemm.py's `launch`: persistent grid of 148, its
block and dynamic shared memory, cluster 1, PDL off): tensor maps by value as 128-byte
structs, scale factors as int32 maps. `<kernel>.<case>.launch.json` checks races only.
"""

import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
SURVEY = HERE.parent / "survey" / "DeepGEMM"
TMA_DTYPE = {"e4m3": "u8", "bf16": "bf16", "int32": "s32", "f32": "f32"}
ARRAY_DTYPE = {"e4m3": "e4m3", "bf16": "bf16", "int32": "i32", "f32": "f32"}


def tensor_map(name, t):
    swizzle = {None: "none", 0: "none", 32: "32B", 64: "64B", 128: "128B"}[t.get("swizzle_bytes")]
    return {"name": name, "struct": [{"name": f"{name} tensor map", "offset": 0, "tensor_map": {
        "array": name, "dtype": TMA_DTYPE[t["dtype"]], "dims": t["global_dims"],
        "strides": t["global_stride_bytes"], "box": t["box_dims"], "swizzle": swizzle}}]}


def maps(meta, outputs):
    """The tensor maps' arrays and parameters, in the kernel's parameter order."""
    arrays, params = [], []
    order = [p["source_name"] for p in meta["entries"][0]["params"]]
    for name in sorted(meta["tensor_maps"], key=order.index):
        t = meta["tensor_maps"][name]
        dims = t["global_dims"]
        rows = (t["global_stride_bytes"][0] // max(1, {"e4m3": 1, "bf16": 2, "int32": 4,
                "f32": 4}[t["dtype"]]) if t["global_stride_bytes"] and t["global_stride_bytes"][0] else dims[0])
        shape = [*reversed(dims[1:]), max(dims[0], rows)] if len(dims) > 1 else dims
        dtype = ARRAY_DTYPE[t["dtype"]]
        # An int32 scale-factor word packs four UE8M0 factors: one symbolic byte each.
        if dtype == "i32":
            dtype, shape = "u8", [*shape[:-1], 4 * shape[-1]]
        arrays.append({"name": name, "kind": "out" if name in outputs else "in",
                       "dtype": dtype, "shape": shape})
        params.append(tensor_map(name, t))
    return arrays, params


def launch(meta, description, arrays, params, extra_arrays=()):
    run = meta["launch"]
    return {"description": description, "kernel": meta["entries"][0]["name"], "grid": run["grid"],
            "block": run["block"][0], "cluster": [1, 1, 1],
            "dynamic_shared_bytes": run["dynamic_smem_bytes"],
            "arrays": [*extra_arrays, *arrays], "params": params}


def gemm(stem, kind):
    meta = json.loads((SURVEY / f"{stem}.json").read_text())
    arrays, tmaps = maps(meta, {"tensor_map_cd"})
    params = [{"name": "grouped_layout (nullptr)", "int": 0}, {"name": "shape_m", "int": 128},
              {"name": "shape_n", "int": 128}, {"name": "shape_k", "int": 256},
              {"name": "epilogue args (alpha = 1.0f at 20)", "struct": [{"offset": 20, "u32": 1065353216}]},
              *tmaps]
    return launch(meta, f"DeepGEMM {kind}, M = N = 128, K = 256, the heuristics' config, persistent "
                  "grid 148; races only. Generated by external/ptx/deepgemm/launches.py.", arrays, params)


def mqa():
    meta = json.loads((SURVEY / "sm100_mqa_logits.h64d128_e4m3.json").read_text())
    arrays, tmaps = maps(meta, set())
    q_tokens, kv_tokens = 4, 1024
    extra = [{"name": "cu_seq_len_k_start", "kind": "index", "dtype": "u32", "shape": [q_tokens],
              "contents": [0] * q_tokens},
             {"name": "cu_seq_len_k_end", "kind": "index", "dtype": "u32", "shape": [q_tokens],
              "contents": [kv_tokens] * q_tokens},
             {"name": "logits", "kind": "out", "dtype": "bf16", "shape": [q_tokens, kv_tokens]}]
    params = [{"name": "num_q_tokens", "int": q_tokens}, {"name": "num_kv_tokens", "int": kv_tokens},
              {"name": "logits_stride", "int": kv_tokens}, {"ptr": "cu_seq_len_k_start"},
              {"ptr": "cu_seq_len_k_end"}, {"name": "schedule_meta (nullptr)", "int": 0},
              {"ptr": "logits"}, *tmaps]
    return launch(meta, "DeepGEMM sm100_mqa_logits (DeepSeek-V3.2 indexer: 64 heads of 128, fp8), "
                  f"{q_tokens} q tokens over {kv_tokens} kv tokens each, persistent grid 148; races "
                  "only. Generated by external/ptx/deepgemm/launches.py.", arrays, params, extra)


def main():
    files = {
        "sm100_fp8_gemm.m128n128k256": gemm("sm100_fp8_fp4_gemm_1d1d.m128n128k256_e4m3_bf16out",
                                            "sm100_fp8_fp4_gemm_1d1d (FP8 1D1D-scaled GEMM)"),
        "sm100_mqa_logits.h64d128_q4_kv1024": mqa(),
    }
    for stem, data in files.items():
        (HERE / f"{stem}.launch.json").write_text(json.dumps(data, indent=2) + "\n")
        print("wrote", stem)


if __name__ == "__main__":
    main()
